/* Store finance presentation only: reuse existing controls, data and handlers. */
(()=>{'use strict';if(window.pb1442StoreFinance)return;window.pb1442StoreFinance=true;
const q=(s,r=document)=>r.querySelector(s),all=(s,r=document)=>[...r.querySelectorAll(s)];let queued=false,entered=false,active='debtors';
const visible=n=>n&&n.getClientRects().length&&getComputedStyle(n).display!=='none'&&!n.classList.contains('hidden');
function show(n,on){if(n&&n.hidden===on)n.hidden=!on}
function choose(name){active=name==='overview'?'debtors':name;window.pb857SetAccountingTab?.(active);schedule()}
function options(source,target){if(!source||!target)return;const value=target.value,html='<option value="">همهٔ عکاسی‌ها</option>'+all('option',source).filter(o=>o.value).map(o=>o.outerHTML).join('');if(target.innerHTML!==html){target.innerHTML=html;target.value=all('option',target).some(o=>o.value===value)?value:''}}
function filterPayments(){const select=q('#pb1442PaymentCustomer');if(!select)return;const id=select.value,entries=typeof accountingData==='undefined'?[]:[...(accountingData?.entries||[])].sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0)),rows=all('#accountingEntries tbody>tr');if(rows.length!==entries.length)return;rows.forEach((row,i)=>show(row,!id||String(entries[i].photographer_id)===id))}
function mount(){queued=false;const root=q('#accounting'),tabs=q('#pb856FinanceHeaderContext .pb856FinanceTabs');if(!root||!tabs)return;
 const on=visible(root)&&document.body.classList.contains('rentalAppReady');if(!on){entered=false;if(document.body.classList.contains('pb1442StoreFinance'))document.body.classList.remove('pb1442StoreFinance');const bar=q('#pb1442StoreBar');show(bar,false);const dialog=q('#pb1442PaymentDialog');if(dialog?.open)dialog.close();return}
 if(!document.body.classList.contains('pb1442StoreFinance'))document.body.classList.add('pb1442StoreFinance');
 for(const [index,key,label]of [['0','debtors','داشبورد'],['1','invoices','فاکتورها'],['2','payments','دریافتی‌ها'],['3','ledger','حساب معین']]){const button=q('[data-pb842-tab="'+key+'"]',tabs);if(!button)continue;if(button.textContent!==label)button.textContent=label;if(tabs.children[Number(index)]!==button)tabs.insertBefore(button,tabs.children[Number(index)]||null)}
 const shell=q('.pb856FinanceShell',root)||root;let overview=q('.pb1442Overview',root);if(!overview){overview=document.createElement('section');overview.className='pb1442Overview';const title=document.createElement('h2');title.textContent='داشبورد امور مالی';overview.append(title);shell.prepend(overview)}const summary=q('.pb856FinanceSummary',root);if(summary&&summary.parentNode!==overview)overview.append(summary);
 let bar=q('#pb1442StoreBar');if(!bar){bar=document.createElement('div');bar.id='pb1442StoreBar';bar.className='pb1442StoreBar';bar.setAttribute('aria-label','ابزارهای امور مالی');bar.innerHTML='<div data-pb1442-mode="invoices"></div><div data-pb1442-mode="ledger"></div><div data-pb1442-mode="payments"><select id="pb1442PaymentCustomer" aria-label="انتخاب عکاسی برای دریافتی‌ها"></select><button type="button" id="pb1442NewPayment">＋ ثبت دریافت</button></div>';shell.prepend(bar);q('#pb1442PaymentCustomer').addEventListener('change',filterPayments);q('#pb1442NewPayment').onclick=()=>{const dialog=q('#pb1442PaymentDialog'),select=q('#accPhotographer'),filter=q('#pb1442PaymentCustomer');if(filter.value&&select)select.value=filter.value;dialog?.showModal()}}
 const invoiceHost=q('[data-pb1442-mode="invoices"]',bar),invoiceSelect=q('#pb855FinanceInvoicePhotographer'),count=q('#pb855FinanceInvoiceCount');for(const node of [invoiceSelect,count])if(node&&node.parentNode!==invoiceHost)invoiceHost.append(node);
 const ledgerHost=q('[data-pb1442-mode="ledger"]',bar),ledger=q('.pb856StatementToolbar',root);if(ledger&&ledger.parentNode!==ledgerHost)ledgerHost.append(ledger);
 const form=q('#accountingForm');let dialog=q('#pb1442PaymentDialog');if(form&&!dialog){dialog=document.createElement('dialog');dialog.id='pb1442PaymentDialog';dialog.className='pb1442PaymentDialog';dialog.setAttribute('aria-label','ثبت دریافت فروشگاه');const head=document.createElement('header'),title=document.createElement('h2'),close=document.createElement('button');title.textContent='ثبت دریافت / اصلاح حساب';close.type='button';close.textContent='×';close.setAttribute('aria-label','بستن');close.onclick=()=>dialog.close();head.append(title,close);dialog.append(head,form);const message=q('#accountingMsg');if(message)dialog.append(message);shell.append(dialog);dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})}
 options(q('#accPhotographer'),q('#pb1442PaymentCustomer'));filterPayments();
 if(!entered){entered=true;choose('debtors')}else{const selected=q('[data-pb842-tab].active',tabs);if(selected)active=selected.dataset.pb842Tab}
 show(overview,active==='debtors');show(bar,active!=='debtors');all('[data-pb1442-mode]',bar).forEach(n=>show(n,n.dataset.pb1442Mode===active));
 const edge=Math.ceil(Math.max(0,...all('body>header.top,#rentalDesktopPrimaryNav,#rentalHeaderFilterHost').filter(visible).map(n=>n.getBoundingClientRect().bottom)));if(edge>0&&edge<innerHeight-80){const value=edge+'px';if(bar.style.getPropertyValue('--pb1442-top')!==value)bar.style.setProperty('--pb1442-top',value)}
 root.style.setProperty('--pb1442-space',active==='debtors'?'0px':'62px');
}
function schedule(){if(!queued){queued=true;requestAnimationFrame(mount)}}
function start(){const root=q('#accounting');if(!root)return;new MutationObserver(schedule).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class','hidden']});addEventListener('resize',schedule);addEventListener('popstate',schedule);document.addEventListener('click',schedule);if(typeof ResizeObserver==='function'){const observer=new ResizeObserver(schedule);all('body>header.top,#rentalDesktopPrimaryNav,#rentalHeaderFilterHost').forEach(n=>observer.observe(n))}schedule()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
